// The link fixture for fractal-engine's `link` module: the website's own `permalink.js`
// and `deep-link.js` run over a spread of real links, and what each one parsed to.
//
//   node make-link-cases.mjs <fractal-website checkout> > engine/fixtures/link-cases.json
//
// Read-only over the website: it imports the contract modules and the committed
// engine.wasm (for `plan`'s home views and the width cap), exactly as builder/emit.mjs
// does, and writes nothing there.

import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { execFileSync } from "node:child_process";

const site = process.argv[2];
const url = (path) => pathToFileURL(join(site, path)).href;
const permalink = await import(url("explorer/permalink.js"));
const deep = await import(url("explorer/deep-link.js"));
const { DEFAULT_PALETTE, PALETTES } = await import(url("explorer/palettes.js"));
const { familySpecOf } = await import(url("explorer/render.js"));
const { CONSTANTS, SETTLED } = await import(url("explorer/catalog.js"));

const engine = new WebAssembly.Instance(
  new WebAssembly.Module(readFileSync(join(site, "explorer/engine.wasm"))),
  {},
).exports;

function plan(spec) {
  const raw = new TextEncoder().encode(JSON.stringify(spec));
  const pointer = engine.alloc(raw.length);
  new Uint8Array(engine.memory.buffer, pointer, raw.length).set(raw);
  const out = engine.plan(pointer, raw.length);
  engine.dealloc(pointer, raw.length);
  const size = new DataView(engine.memory.buffer).getUint32(out, true);
  const body = new TextDecoder().decode(new Uint8Array(engine.memory.buffer, out + 4, size));
  engine.dealloc(out, size + 4);
  return JSON.parse(body);
}

function seedConstants(family) {
  const held = {};
  for (const [key, text] of Object.entries(CONSTANTS[family] ?? {})) {
    held[key] = { text, value: Number(text) };
  }
  return held;
}

const homes = new Map();
function homeOf(family) {
  if (!homes.has(family)) {
    const answer = plan({ schema: 1, family: familySpecOf(family, seedConstants(family)) });
    if (!answer.ok) throw new Error(`${family}: ${answer.why}`);
    homes.set(family, {
      x: permalink.coordinateOf(answer.home.x),
      y: permalink.coordinateOf(answer.home.y),
      w: permalink.coordinateOf(answer.home.w),
    });
  }
  return homes.get(family);
}

const cap = (width) => engine.maxiter_for_width(width);
const shallowContext = {
  home: homeOf,
  constants: seedConstants,
  palettes: PALETTES,
  defaultPalette: DEFAULT_PALETTE,
  settled: (mode) => SETTLED[mode],
  cap,
};
const deepContext = {
  palettes: PALETTES,
  defaultPalette: DEFAULT_PALETTE,
  deepHome: (family = "mandelbrot") => {
    const home = homeOf(family);
    return { x: home.x.text, y: home.y.text, w: home.w.text };
  },
  deepCap: cap,
};

// ------------------------------------------------------------------ the links

const jsonl = (path) =>
  readFileSync(join(site, path), "utf8")
    .split("\n")
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line));

const cases = [];
const seen = new Set();
function add(source, query) {
  if (seen.has(query)) return;
  seen.add(query);
  cases.push({ source, query });
}

// Gallery seats: every collection, a stride through each so every mode and family shows.
const seatDir = "assets/images/galleries/seated-candidates";
for (const file of readdirSync(join(site, seatDir)).sort()) {
  if (!file.endsWith(".jsonl")) continue;
  const rows = jsonl(`${seatDir}/${file}`).filter((row) => typeof row.link === "string");
  const stride = Math.max(1, Math.floor(rows.length / 8));
  for (let at = 0; at < rows.length; at += stride) add(`seat:${file}`, rows[at].link);
}
// And every mode the seats carry at least once, from the full general-2000 record.
const byMode = new Map();
for (const row of jsonl(`${seatDir}/general-2000.jsonl`)) {
  if (typeof row.link === "string" && !byMode.has(row.mode)) byMode.set(row.mode, row.link);
}
for (const [mode, link] of byMode) add(`seat-mode:${mode}`, link);

// The 31 Deep gallery rows.
for (const row of jsonl("explorer/deep-gallery.jsonl")) add("deep-gallery", row.link);

// Figure links: every explorer query the article's pages and figure records name.
const figureText = [
  ...readdirSync(join(site, "article"))
    .filter((file) => file.endsWith(".html") || file.endsWith(".jsonl"))
    .map((file) => readFileSync(join(site, "article", file), "utf8")),
].join("\n");
for (const found of figureText.matchAll(/explorer\/(?:index\.html)?\?((?:d?v)=[^"'<>\s#]+)/g)) {
  add("figure", found[1].replaceAll("&amp;", "&"));
}

