for (const query of corners) add("corner", query);

// ------------------------------------------------------------------ the answers

const shade = (value) => value;
function shallowView(view) {
  const constants = {};
  for (const [key, held] of Object.entries(view.constants)) constants[key] = held.text;
  return {
    family: view.family,
    constants,
    mode: view.mode,
    params: view.params,
    x: view.x.text,
    y: view.y.text,
    w: view.w.text,
    maxiter: view.maxiter,
    aspect: [view.aspect.across, view.aspect.down],
    palette: view.palette,
    shade: shade(view.shade),
    level: view.level,
  };
}
function deepView(view) {
  return {
    degree: view.degree,
    julia: view.julia === null ? null : [view.julia.x.text, view.julia.y.text],
    x: view.x.text,
    y: view.y.text,
    w: view.w.text,
    maxiter: view.capFrom === "width" ? null : view.maxiter,
    aspect: [view.aspect.across, view.aspect.down],
    palette: view.palette,
    shade: shade(view.shade),
    level: view.level,
  };
}

const out = [];
for (const { source, query } of cases) {
  const isDeep = permalink.isDeep(query);
  const row = { source, query, deep: isDeep };
  try {
    if (isDeep) {
      row.view = deepView(deep.parse(query, deepContext));
      row.canonical = deep.canonicalize(query, deepContext);
    } else {
      row.view = shallowView(permalink.parse(query, shallowContext));
      row.canonical = permalink.canonicalize(query, shallowContext);
    }
    row.ok = true;
  } catch (error) {
    if (!(error instanceof permalink.PermalinkError)) throw error;
    row.ok = false;
    row.why = error.message;
  }
  out.push(row);
}

